entries[48677] = { ["name"] = "Champion's Deathdealer Breastplate", ["text"] = "Binds to Warband\nChest Mail\n3 Armor\nRegalia of Fabled Adventurers (0/7)\nHeirloom Chestpiece\nHeirloom Helm\nHeirloom Shoulders\nHeirloom Cloak\nHeirloom Legs\nHeirloom Necklace\nHeirloom Ring\n(2) Set : Rested experience consumed is reduced by 30%.\n(3) Set : Increases your out-of-combat regeneration in the outdoors, normal dungeons and battlegrounds.\n(5) Set : Gaining a level triggers Burst of Knowledge, dealing 26225 Holy damage to nearby enemies and granting you 40% Primary Stat for 2 min. Defeating enemies extends this effect, up to an additional 2 min.\n(6) Set : Rested experience consumed is reduced by an additional 30%." }
