entries[48768] = { ["name"] = "Kablooey Bombs", ["text"] = "Quest Item\nUnique\nUse: Toss the Kablooey Bomb up to 5 yards to blow a Kaja'mite Deposit to smithereens. Then all you have to do is pick up the remaining chunks. While you're at it, you can use the Kablooey Bombs to stun those unruly Rebellious Trolls! (5 Sec Cooldown)" }
